class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" -- "*" Furniture : consists of
Furniture "*" -- "*" ComponentType : composed of
Furniture "*" -- "*" Store : sold in
Store "1" -- "*" Order : places
Order "*" -- "*" Furniture : contains
Order "*" -- "1" OrderLine
Furniture "*" -- "1" OrderLine

@enduml

